from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
left_wheel = Motor(Port.A, Direction.COUNTERCLOCKWISE)
right_wheel = Motor(Port.E, Direction.CLOCKWISE)
robot = DriveBase(left_wheel, right_wheel, 88, 146)
back_atachment = Motor(Port.C, Direction.COUNTERCLOCKWISE)


# The main program starts here.
print('Hello, Pybricks!')
# line square in front of mission 7
robot.turn(180)
robot.straight(-50)
back_atachment.run_angle(500, -150)
back_atachment.run_angle(500, 120)
robot.turn(80)
back_atachment.run_angle(500, 20)
robot.straight(-150)
back_atachment.run_angle(1000, -70)
